# Provider config. No credentials live here — auth comes from the ambient `az
# login` session (Owner on the subscription) or ARM_*/AZURE_* env vars. This
# stack applies as the Owner user (not the harness's Contributor-only SP), so it
# CAN register resource providers (rp.tf) and create role assignments
# (identity.tf / github_oidc.tf).

provider "azurerm" {
  features {
    key_vault {
      # Purge soft-deleted vaults on destroy so a re-apply can reuse the name.
      purge_soft_delete_on_destroy = true
    }
  }
  # We register the 4 missing RPs explicitly in rp.tf; don't let the provider
  # mass-register every RP on the subscription.
  resource_provider_registrations = "none"
}

provider "azuread" {
  # Tenant comes from the az login session (Default Directory). Creating the
  # GitHub-deploy app registration needs app-registration rights — fine as the
  # directory owner.
}

provider "random" {}
provider "time" {}
provider "null" {}

# this. See the guardrail row in docs/progress.md.

data "azurerm_postgresql_flexible_server" "shared" {
  name                = var.shared_pg_server_name
  resource_group_name = data.azurerm_resource_group.dataq.name
}

locals {
  # psycopg2 URL the backend Settings read as DATABASE_URL. sslmode=require —
  # Flexible Server enforces TLS. The password is URL-encoded so a future value
  # containing URL-significant chars (@ : / ? #) can't break DSN parsing (#395);
  # app_db_user/name are controlled alnum identifiers, no encoding needed.
  database_url = join("", [
    "postgresql+psycopg2://",
    var.app_db_user, ":", urlencode(var.app_db_password),
    "@", data.azurerm_postgresql_flexible_server.shared.fqdn, ":5432/",
    var.app_db_name, "?sslmode=require",
  ])
}

